algorithms.code:
check(address) { const snapshot=active; const ip=parseStrictIPv4(address);
 if(ip===INVALID)return deny("invalid",snapshot.version);
 for(const r of snapshot.rules) if(unsigned(ip&r.mask)===r.network)
  return {decision:r.action,ruleOrdinal:r.ordinal,policyVersion:snapshot.version};
 return deny("unmatched",snapshot.version);
}
replaceRules(rules) { const candidate=rules.map(compileChecked);
 active=immutablePair(candidate,active.version+1); }

lookup(ip) { let node=active.root, best=null;
 for(let depth=0; node && depth<=32; depth++) {
  if(node.candidate && (!best || node.candidate.ordinal<best.ordinal)) best=node.candidate;
  if(depth===32)break; node=node.child[(ip >>> (31-depth)) & 1];
 } return best ?? DEFAULT_DENY;
}
// During build, root handles /0; exact prefix duplicates retain minimum ordinal.
// Publish the entire root/version pair only after every rule parses.
